INSERT OR IGNORE INTO lead_sources
  (id, name, slug, type, base_url, enabled, automation_allowed, crawl_allowed,
   policy_status, policy_notes, parser_version, created_at, updated_at)
VALUES ('ebcaaf31-ed5e-4c8a-a3b0-b76adac13fe9', 'OpenStreetMap (Overpass API)', 'osm-overpass', 'osm_overpass', 'https://overpass-api.de/api/interpreter',
        0, 0, 0, 'unreviewed', 'Data is ODbL-licensed and openly available. Before enabling, review the current public instance guidance (https://wiki.openstreetmap.org/wiki/Overpass_API) and the policy of the exact endpoint configured. The main public instance directs regular commercial use to self-hosted or paid infrastructure. The adapter is sequential and bounded, but that does not itself grant permission to use an endpoint. Attribution: OSM data must be credited where it is displayed publicly. It is not displayed publicly here — it is internal research evidence only.', 1, '2026-09-18T15:24:20.702Z', '2026-09-18T15:24:20.702Z');

INSERT OR IGNORE INTO lead_sources
  (id, name, slug, type, base_url, enabled, automation_allowed, crawl_allowed,
   policy_status, policy_notes, parser_version, created_at, updated_at)
VALUES ('8e8c0ec6-ea84-41a9-acd1-5b021e8d8ad0', 'OpenStreetMap (Nominatim search)', 'osm-nominatim', 'search_api', 'https://nominatim.openstreetmap.org/search',
        0, 0, 0, 'unreviewed', 'Free, keyless, ODbL-licensed, over the same OpenStreetMap data as Overpass but asking a free-text question rather than a tag-and-bbox one. Before enabling, read the Nominatim Usage Policy (https://operations.osmfoundation.org/policies/nominatim/): it caps automated clients at ONE REQUEST PER SECOND as an absolute limit, requires an identifying User-Agent, and asks heavy users to self-host. The adapter enforces the interval with a real delay and keeps the per-run budget small, but that does not itself grant permission. Note on query phrasing: Nominatim resolves OSM special phrases, so "dentist Austin TX" and "law firm Houston" return results where "hvac contractor Phoenix" returns none. A zero-result query is reported per query so it can be rewritten. Attribution: OSM data must be credited where it is displayed publicly. It is not displayed publicly here — it is internal research evidence only.', 1, '2026-09-18T15:24:20.702Z', '2026-09-18T15:24:20.702Z');

INSERT OR IGNORE INTO lead_sources
  (id, name, slug, type, base_url, enabled, automation_allowed, crawl_allowed,
   policy_status, policy_notes, parser_version, created_at, updated_at)
VALUES ('9051fcb1-bd97-40d2-9dec-3d34584f76ef', 'Brave Search API', 'brave-search', 'search_api', 'https://api.search.brave.com/res/v1/web/search',
        0, 0, 0, 'unreviewed', 'A paid, documented API with its own terms. Before enabling, confirm the plan permits this use and note the request quota. The adapter is entirely optional: with no API key the engine works and simply discovers fewer candidates. Snippets are never forwarded to Workers AI — Brave is used for domain discovery only.', 1, '2026-09-18T15:24:20.702Z', '2026-09-18T15:24:20.702Z');

INSERT OR IGNORE INTO lead_sources
  (id, name, slug, type, base_url, enabled, automation_allowed, crawl_allowed,
   policy_status, policy_notes, parser_version, created_at, updated_at)
VALUES ('f301c301-b451-4eb4-8626-9806507d6e61', 'Manual import (CSV / domain list)', 'manual-import', 'manual_import', NULL,
        0, 0, 0, 'unreviewed', 'Candidates an operator pastes in by hand. No third-party terms apply to the import itself, but the SOURCE of the list does matter: do not import a purchased list. Imported rows go through the same normalization, deduplication and compliance gate as anything an automated adapter found.', 1, '2026-09-18T15:24:20.702Z', '2026-09-18T15:24:20.702Z');

